addEventListener("fetch", (event) => {
  event.respondWith(handle(event));
});

const ROBOTS = "noindex, nofollow, noarchive, nosnippet, noimageindex, noai, noimageai";
const BOT = /(bot\b|crawler|spider|scraper|slurp|archiver|wget|python-requests|scrapy|headlesschrome|phantomjs|curl\/|gptbot|chatgpt|claude|anthropic|ccbot|bytespider|amazonbot|petalbot|semrush|ahrefs|mj12|dotbot|dataforseo|diffbot|imagesift|perplexity|youbot|cohere|ai2bot|timpibot|omgili|facebookexternalhit|meta-external|google-extended|googleother|applebot|oai-search)/i;
const FILES = {
  "/index.html": ["", "text/html; charset=utf-8", "public, max-age=120"],
  "/robots.txt": ["", "text/plain; charset=utf-8", "public, max-age=3600"],
  "/favicon.svg": ["", "image/svg+xml", "public, max-age=86400"],
  "/assets/styles-B0EVTgND.css": ["", "text/css; charset=utf-8", "public, max-age=86400"],
  "/assets/routes-_kB-fYQx.js": ["", "application/javascript; charset=utf-8", "public, max-age=86400"],
  "/assets/index-B39cmyQg.js": ["", "application/javascript; charset=utf-8", "public, max-age=86400"]
};

function denied() {
  return new Response("Crawling is not allowed.", {
    status: 403,
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "x-robots-tag": ROBOTS,
      "cache-control": "no-store",
    },
  });
}

function inflate(b64) {
  const raw = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return new Blob([raw]).stream().pipeThrough(new DecompressionStream("gzip"));
}

async function handle(event) {
  const ua = event.request.headers.get("user-agent") || "";
  if (BOT.test(ua)) return denied();
  const url = new URL(event.request.url);
  let path = url.pathname;
  if (path.length > 1 && path.endsWith("/")) path = path.slice(0, -1);
  if (path === "/") path = "/index.html";
  const file = FILES[path];
  if (!file) {
    return new Response("Not found", {
      status: 404,
      headers: { "x-robots-tag": ROBOTS, "cache-control": "no-store" },
    });
  }
  const cache = caches.default;
  const cacheKey = new Request(url.origin + path, { method: "GET" });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const response = new Response(inflate(file[0]), {
    status: 200,
    headers: {
      "content-type": file[1],
      "x-robots-tag": ROBOTS,
      "cache-control": file[2],
    },
  });
  event.waitUntil(cache.put(cacheKey, response.clone()));
  return response;
}
